public Map<String, Object> sortByPrice(ArrayList<Product> products) {	
      Map<String, Object> list = new TreeMap<String, Object>();
      foreach(Product product : products){
          JSONB obj = JsonUtils.nullAsNull(JsonUtils.toJson(product));
          list.put(obj["product ID"], obj);
      }
      return list;
}

